import{_ as r,c as a,o as t,aj as o}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: CronTriggersAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/CronTriggersAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/CronTriggersAPI.md"}'),d={name:"reference/js-bao-wss-client/api/interfaces/CronTriggersAPI.md"};function i(n,e,s,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / CronTriggersAPI</p><h1 id="interface-crontriggersapi" tabindex="-1">Interface: CronTriggersAPI <a class="header-anchor" href="#interface-crontriggersapi" aria-label="Permalink to “Interface: CronTriggersAPI”">​</a></h1><p>Sub-API for cron triggers (<code>client.cronTriggers.*</code>). A cron trigger runs a workflow on a recurring schedule defined by a cron expression and timezone. Supports the full lifecycle: create, update, disable/enable, test-fire, and archive.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="create" tabindex="-1">create() <a class="header-anchor" href="#create" aria-label="Permalink to “create()”">​</a></h3><blockquote><p><strong>create</strong>&lt;<code>I</code>&gt;(<code>params</code>): <code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p></blockquote><p>Create a new cron trigger. The trigger&#39;s scheduler is provisioned and the first fire is scheduled as part of this call.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to “I”">​</a></h5><p><code>I</code> = <code>unknown</code></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="params" tabindex="-1">params <a class="header-anchor" href="#params" aria-label="Permalink to “params”">​</a></h5><p><a href="./CreateCronTriggerParams.html"><code>CreateCronTriggerParams</code></a>&lt;<code>I</code>&gt;</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p><hr><h3 id="delete" tabindex="-1">delete() <a class="header-anchor" href="#delete" aria-label="Permalink to “delete()”">​</a></h3><blockquote><p><strong>delete</strong>(<code>triggerId</code>): <code>Promise</code>&lt;{ <code>archived</code>: <code>boolean</code>; }&gt;</p></blockquote><p>Soft-delete (archive) a cron trigger and cancel its next scheduled fire.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="triggerid" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid" aria-label="Permalink to “triggerId”">​</a></h5><p><code>string</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>archived</code>: <code>boolean</code>; }&gt;</p><hr><h3 id="disable" tabindex="-1">disable() <a class="header-anchor" href="#disable" aria-label="Permalink to “disable()”">​</a></h3><blockquote><p><strong>disable</strong>(<code>triggerId</code>): <code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p></blockquote><p>Take a trigger out of service. The next scheduled fire is cancelled and no further runs start until <code>enable()</code>.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="triggerid-1" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid-1" aria-label="Permalink to “triggerId”">​</a></h5><p><code>string</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p><hr><h3 id="enable" tabindex="-1">enable() <a class="header-anchor" href="#enable" aria-label="Permalink to “enable()”">​</a></h3><blockquote><p><strong>enable</strong>(<code>triggerId</code>): <code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p></blockquote><p>Put a trigger back in service. Clears <code>lastError</code> and reschedules the next fire. Refuses an archived trigger — that is a delete, not a pause.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="triggerid-2" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid-2" aria-label="Permalink to “triggerId”">​</a></h5><p><code>string</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>triggerId</code>): <code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p></blockquote><p>Get a cron trigger by id, including live runtime state.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="triggerid-3" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid-3" aria-label="Permalink to “triggerId”">​</a></h5><p><code>string</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(): <code>Promise</code>&lt;<a href="./CronTriggerListResult.html"><code>CronTriggerListResult</code></a>&gt;</p></blockquote><p>List all cron triggers for the current app. Archived triggers are excluded.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./CronTriggerListResult.html"><code>CronTriggerListResult</code></a>&gt;</p><hr><h3 id="test" tabindex="-1">test() <a class="header-anchor" href="#test" aria-label="Permalink to “test()”">​</a></h3><blockquote><p><strong>test</strong>(<code>triggerId</code>): <code>Promise</code>&lt;{ <code>error?</code>: <code>string</code>; <code>instanceId?</code>: <code>string</code>; <code>runId?</code>: <code>string</code>; <code>started</code>: <code>boolean</code>; }&gt;</p></blockquote><p>Fire the associated workflow immediately without affecting the schedule.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="triggerid-4" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid-4" aria-label="Permalink to “triggerId”">​</a></h5><p><code>string</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>error?</code>: <code>string</code>; <code>instanceId?</code>: <code>string</code>; <code>runId?</code>: <code>string</code>; <code>started</code>: <code>boolean</code>; }&gt;</p><hr><h3 id="update" tabindex="-1">update() <a class="header-anchor" href="#update" aria-label="Permalink to “update()”">​</a></h3><blockquote><p><strong>update</strong>&lt;<code>I</code>&gt;(<code>triggerId</code>, <code>params</code>): <code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p></blockquote><p>Update one or more fields of an existing cron trigger. Schedule-relevant field changes (cron, timezone) take effect on the schedule immediately. Availability is not settable here — use <code>disable()</code> / <code>enable()</code>.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="i-1" tabindex="-1">I <a class="header-anchor" href="#i-1" aria-label="Permalink to “I”">​</a></h5><p><code>I</code> = <code>unknown</code></p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="triggerid-5" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid-5" aria-label="Permalink to “triggerId”">​</a></h5><p><code>string</code></p><h5 id="params-1" tabindex="-1">params <a class="header-anchor" href="#params-1" aria-label="Permalink to “params”">​</a></h5><p><a href="./UpdateCronTriggerParams.html"><code>UpdateCronTriggerParams</code></a>&lt;<code>I</code>&gt;</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./CronTriggerInfo.html"><code>CronTriggerInfo</code></a>&gt;</p>',82)])])}const m=r(d,[["render",i]]);export{p as __pageData,m as default};
